MANIFEST = json.loads(zlib.decompress(base64.b64decode(_MANIFEST)).decode())


def repo_root(start: Path) -> Path:
    for d in [start, *start.parents]:
        if (d / "package.json").exists() or (d / ".git").exists():
            return d
    return start


def main() -> int:
    check = "--check" in sys.argv
    here = Path(__file__).resolve().parent
    root = repo_root(here)
    target = root / "design"
    print(f"repository root : {root}")
    print(f"kit             : {target}")

    payload = json.loads(zlib.decompress(base64.b64decode(_BLOB)).decode())

    written, same, missing, differs = 0, 0, [], []
    for rel, b64 in sorted(payload.items()):
        data = base64.b64decode(b64)
        dest = target / rel
        if check:
            if not dest.exists():
                missing.append(rel)
            elif hashlib.sha256(dest.read_bytes()).hexdigest()[:16] != MANIFEST[rel]:
                differs.append(rel)
            else:
                same += 1
            continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        if dest.exists() and dest.read_bytes() == data:
            same += 1
            continue
        dest.write_bytes(data)
        written += 1

    if check:
        print(f"\nmatching : {same}")
        print(f"missing  : {len(missing)}" + (" -> " + ", ".join(missing[:6]) if missing else ""))
        print(f"changed  : {len(differs)}" + (" -> " + ", ".join(differs[:6]) if differs else ""))
        if missing or differs:
            print("\nRun without --check to restore them.")
            return 1
        print("\nThe kit on disk matches this script.")
        return 0

    print(f"\nwritten   : {written}")
    print(f"unchanged : {same}")
    print(f"total     : {written + same} files")
    print("\nNext:")
    print("  git add design && git commit -m 'UI-P00: add design kit'")
    print("  then run design/prompts/UI-P00.md")
    print("\nOpen any design/reference/**/*.html in a browser - it needs nothing else.")
    return 0


